import { describe, it, expect } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt.ts";

const R = 6371000;
describe("tiltGlobeCamera", () => {
    it("tilts a fresh camera at full zoom-out and keeps zoom/heading/centre", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        setGeospatialOrientation(cam, { yaw: 0.7, center: { x: R * 0.6, y: R * 0.3, z: R * 0.74 } });
        const before = { yaw: cam.yaw, radius: cam.radius, center: { ...cam.center } };
        for (const p of [0.1, 0.6, 1.2]) {
            tiltGlobeCamera(cam, p);
            expect(cam.pitch).toBeCloseTo(p, 9);
            expect(cam.radius).toBeCloseTo(before.radius, 6);
            expect(cam.yaw).toBeCloseTo(before.yaw, 9);
            expect(cam.center.x).toBeCloseTo(before.center.x, 3);
            expect(cam.center.y).toBeCloseTo(before.center.y, 3);
            expect(cam.center.z).toBeCloseTo(before.center.z, 3);
            // look direction really points at the tilt: dot(lookAt, -up_geo) = cos(pitch)
            const c = cam.center; const cl = Math.hypot(c.x, c.y, c.z);
            const dot = -(cam._lookAt.x * c.x + cam._lookAt.y * c.y + cam._lookAt.z * c.z) / cl;
            expect(dot).toBeCloseTo(Math.cos(p), 5);
        }
        // zoom in and out later: tilt stays
        cam.radius = 500000;
        expect(cam.pitch).toBeCloseTo(1.2, 9);
        cam.radius = R * 4;
        expect(cam.pitch).toBeCloseTo(1.2, 9);
        cam.radius = 1000;
        expect(cam.pitch).toBeCloseTo(1.2, 9);
    });
});
